Hypothesis H_pc : CC.cp_pc cp0 = PML.PC_APPEND_RANGE.
Hypothesis H_BL0 : nth 0 BLS [] = [(e_p, CAP)].
Hypothesis H_kn : kn_chk s0 below cp0 = true.
